50	// LoadFromRegistry populates the in-memory index from the durable
51	// StoreRegistry. Call once during startup.
52	func (m *Manager) LoadFromRegistry(ctx context.Context) error {
53		stores, err := m.registry.ListStores(ctx)
54		if err != nil {
55			return fmt.Errorf("load vector store registry: %w", err)
56		}
57	
58		m.mu.Lock()
59		defer m.mu.Unlock()
60		for _, vs := range stores {
61			m.stores[vs.ID] = cloneVectorStore(vs)
62		}
63		return nil
64	}
