74	type UpdateStoreRequest struct {
75		Name         *string                `json:"name,omitempty"`
76		ExpiresAfter *ExpirationPolicy      `json:"expires_after,omitempty"`
77		Metadata     map[string]interface{} `json:"metadata,omitempty"`
78	}
