88	// CreateStore creates a new vector store and its backing collection.
89	func (m *Manager) CreateStore(ctx context.Context, req CreateStoreRequest) (*VectorStore, error) {
90		id := GenerateVectorStoreID()
91	
92		if err := m.backend.CreateCollection(ctx, id, m.embeddingDim); err != nil {
93			return nil, fmt.Errorf("failed to create backend collection: %w", err)
94		}
95	
96		vs := &VectorStore{
97			ID:           id,
98			Object:       "vector_store",
99			Name:         req.Name,
100			CreatedAt:    time.Now().Unix(),
101			Status:       "active",
102			FileCounts:   FileCounts{},
103			ExpiresAfter: cloneExpirationPolicy(req.ExpiresAfter),
104			Metadata:     cloneMetadata(req.Metadata),
105			BackendType:  m.defaultBackendType,
106		}
107	
108		m.mu.Lock()
109		m.stores[id] = cloneVectorStore(vs)
110		m.mu.Unlock()
111	
112		if err := m.registry.SaveStore(ctx, cloneVectorStore(vs)); err != nil {
113			return cloneVectorStore(vs), fmt.Errorf("persist vector store metadata: %w", err)
114		}
115		return cloneVectorStore(vs), nil
116	}
117	
118	// GetStore returns a vector store by ID.
119	func (m *Manager) GetStore(id string) (*VectorStore, error) {
120		m.mu.RLock()
121		defer m.mu.RUnlock()
122	
123		vs, ok := m.stores[id]
124		if !ok {
125			return nil, fmt.Errorf("vector store not found: %s", id)
126		}
127		return cloneVectorStore(vs), nil
128	}
