130	// ListStores returns vector stores with pagination.
131	func (m *Manager) ListStores(params ListStoresParams) []*VectorStore {
132		params = normalizeListStoresParams(params)
133	
134		m.mu.RLock()
135		all := make([]*VectorStore, 0, len(m.stores))
136		for _, vs := range m.stores {
137			all = append(all, cloneVectorStore(vs))
138		}
139		m.mu.RUnlock()
140	
141		sortVectorStores(all, params.Order)
142		return pageVectorStores(all, params)
143	}
144	
145	func normalizeListStoresParams(params ListStoresParams) ListStoresParams {
146		if params.Limit <= 0 {
147			params.Limit = 20
148		}
149		if params.Limit > 100 {
150			params.Limit = 100
151		}
152		if params.Order != "asc" {
153			params.Order = "desc"
154		}
155		return params
156	}
157	
158	func sortVectorStores(stores []*VectorStore, order string) {
159		if order == "asc" {
160			sort.Slice(stores, func(i, j int) bool { return stores[i].CreatedAt < stores[j].CreatedAt })
161		} else {
162			sort.Slice(stores, func(i, j int) bool { return stores[i].CreatedAt > stores[j].CreatedAt })
163		}
164	}
165	
166	func pageVectorStores(all []*VectorStore, params ListStoresParams) []*VectorStore {
167		startIdx := 0
168		endIdx := len(all)
169	
170		if params.After != "" {
171			for i, vs := range all {
172				if vs.ID == params.After {
173					startIdx = i + 1
174					break
175				}
176			}
177		}
178		if params.Before != "" {
179			for i, vs := range all {
180				if vs.ID == params.Before {
181					endIdx = i
182					break
183				}
184			}
185		}
186	
187		if startIdx >= endIdx {
188			return nil
189		}
190	
191		end := startIdx + params.Limit
192		if end > endIdx {
193			end = endIdx
194		}
195	
196		return all[startIdx:end]
197	}
