239		}
240		if err := m.backend.DeleteCollection(ctx, id); err != nil {
241			return fmt.Errorf("failed to delete backend collection: %w", err)
242		}
243		return nil
244	}
245	
246	// Backend returns the underlying vector store backend for direct operations.
247	func (m *Manager) Backend() VectorStoreBackend {
248		return m.backend
249	}
250	
251	// UpdateFileCounts updates the file counts for a vector store.
252	func (m *Manager) UpdateFileCounts(ctx context.Context, id string, fn func(*FileCounts)) error {
