256			m.mu.Unlock()
257			return fmt.Errorf("vector store not found: %s", id)
258		}
259		fn(&vs.FileCounts)
260		snapshot := cloneVectorStore(vs)
261		m.mu.Unlock()
262	
263		if err := m.registry.SaveStore(ctx, cloneVectorStore(snapshot)); err != nil {
264			return fmt.Errorf("persist vector store metadata: %w", err)
