25	)
26	
27	// MemoryBackendConfig holds configuration for the in-memory backend.
28	type MemoryBackendConfig struct {
29		MaxEntriesPerStore int // Maximum entries per collection (0 = unlimited)
30	}
31	
32	// memoryCollection holds the data for one in-memory vector store collection.
33	type memoryCollection struct {
34		dimension  int
35		chunks     map[string]EmbeddedChunk // chunk ID -> chunk
36		bm25Index  *BM25Index               // rebuilt on chunk mutations
37		ngramIndex *NgramIndex              // rebuilt on chunk mutations
38	}
39	
40	const defaultNgramSize = 3
41	
42	// rebuildTextIndexes rebuilds the BM25 and n-gram indexes from current chunks.
43	func (col *memoryCollection) rebuildTextIndexes() {
44		col.bm25Index = NewBM25Index(col.chunks)
45		col.ngramIndex = NewNgramIndex(col.chunks, defaultNgramSize)
46	}
47	
48	// MemoryBackend implements VectorStoreBackend using in-memory storage
49	// with brute-force cosine similarity search. Intended for development
50	// and testing — data is not persisted across restarts.
51	type MemoryBackend struct {
52		mu          sync.RWMutex
53		collections map[string]*memoryCollection // vectorStoreID -> collection
54		maxEntries  int
55	}
56	
57	// NewMemoryBackend creates a new in-memory vector store backend.
58	func NewMemoryBackend(cfg MemoryBackendConfig) *MemoryBackend {
59		return &MemoryBackend{
60			collections: make(map[string]*memoryCollection),
61			maxEntries:  cfg.MaxEntriesPerStore,
62		}
63	}
64	
65	// CreateCollection creates a new in-memory collection.
66	func (m *MemoryBackend) CreateCollection(_ context.Context, vectorStoreID string, dimension int) error {
67		m.mu.Lock()
68		defer m.mu.Unlock()
69	
70		if _, exists := m.collections[vectorStoreID]; exists {
71			return fmt.Errorf("collection already exists: %s", vectorStoreID)
72		}
73	
74		m.collections[vectorStoreID] = &memoryCollection{
75			dimension: dimension,
76			chunks:    make(map[string]EmbeddedChunk),
77		}
78		return nil
79	}
80	
81	// DeleteCollection removes an in-memory collection.
82	func (m *MemoryBackend) DeleteCollection(_ context.Context, vectorStoreID string) error {
83		m.mu.Lock()
84		defer m.mu.Unlock()
85	
86		if _, exists := m.collections[vectorStoreID]; !exists {
87			return fmt.Errorf("collection not found: %s", vectorStoreID)
88		}
89	
90		delete(m.collections, vectorStoreID)
91		return nil
92	}
93	
94	// CollectionExists checks if a collection exists.
95	func (m *MemoryBackend) CollectionExists(_ context.Context, vectorStoreID string) (bool, error) {
96		m.mu.RLock()
97		defer m.mu.RUnlock()
98	
99		_, exists := m.collections[vectorStoreID]
100		return exists, nil
101	}
102	
103	// InsertChunks inserts embedded chunks into the collection.
104	func (m *MemoryBackend) InsertChunks(_ context.Context, vectorStoreID string, chunks []EmbeddedChunk) error {
105		m.mu.Lock()
106		defer m.mu.Unlock()
107	
108		col, exists := m.collections[vectorStoreID]
109		if !exists {
110			return fmt.Errorf("collection not found: %s", vectorStoreID)
111		}
112	
113		for _, chunk := range chunks {
114			if m.maxEntries > 0 && len(col.chunks) >= m.maxEntries {
115				return fmt.Errorf("collection %s has reached maximum entries (%d)", vectorStoreID, m.maxEntries)
116			}
117			col.chunks[chunk.ID] = chunk
118		}
119	
120		col.rebuildTextIndexes()
121		return nil
122	}
123	
124	// DeleteByFileID removes all chunks associated with a file.
125	func (m *MemoryBackend) DeleteByFileID(_ context.Context, vectorStoreID string, fileID string) error {
126		m.mu.Lock()
127		defer m.mu.Unlock()
128	
129		col, exists := m.collections[vectorStoreID]
130		if !exists {
131			return fmt.Errorf("collection not found: %s", vectorStoreID)
132		}
133	
134		deleted := false
135		for id, chunk := range col.chunks {
136			if chunk.FileID == fileID {
137				delete(col.chunks, id)
138				deleted = true
139			}
140		}
141	
142		if deleted {
143			col.rebuildTextIndexes()
144		}
145		return nil
146	}
147	
148	// Search performs brute-force cosine similarity search.
149	func (m *MemoryBackend) Search(
150		_ context.Context, vectorStoreID string, queryEmbedding []float32,
151		topK int, threshold float32, filter map[string]interface{},
152	) ([]SearchResult, error) {
153		m.mu.RLock()
154		defer m.mu.RUnlock()
155	
156		col, exists := m.collections[vectorStoreID]
157		if !exists {
158			return nil, fmt.Errorf("collection not found: %s", vectorStoreID)
159		}
160	
161		// Extract optional file_id filter.
162		var filterFileID string
163		if filter != nil {
164			if fid, ok := filter["file_id"].(string); ok {
165				filterFileID = fid
166			}
167		}
168	
169		type scored struct {
170			result SearchResult
171			score  float64
172		}
173	
174		var candidates []scored
175		for _, chunk := range col.chunks {
176			if filterFileID != "" && chunk.FileID != filterFileID {
177				continue
178			}
179	
180			sim := cosineSimilarity(queryEmbedding, chunk.Embedding)
181			if sim >= float64(threshold) {
182				candidates = append(candidates, scored{
183					result: SearchResult{
184						FileID:     chunk.FileID,
185						Filename:   chunk.Filename,
186						Content:    chunk.Content,
187						Score:      sim,
188						ChunkIndex: chunk.ChunkIndex,
189					},
190					score: sim,
191				})
192			}
193		}
194	
195		// Sort by score descending.
196		sort.Slice(candidates, func(i, j int) bool {
197			return candidates[i].score > candidates[j].score
198		})
199	
200		if topK > 0 && len(candidates) > topK {
201			candidates = candidates[:topK]
202		}
203	
204		results := make([]SearchResult, len(candidates))
205		for i, c := range candidates {
206			results[i] = c.result
207		}
208		return results, nil
209	}
210	
211	// HybridSearch performs hybrid search combining vector similarity, BM25, and
212	// n-gram scoring. Implements the HybridSearcher interface.
213	func (m *MemoryBackend) HybridSearch(
214		_ context.Context, vectorStoreID string,
215		query string, queryEmbedding []float32,
216		topK int, threshold float32,
217		filter map[string]interface{},
218		config *HybridSearchConfig,
219	) ([]SearchResult, error) {
220		m.mu.RLock()
221		defer m.mu.RUnlock()
222	
223		col, exists := m.collections[vectorStoreID]
224		if !exists {
225			return nil, fmt.Errorf("collection not found: %s", vectorStoreID)
226		}
227	
228		if config == nil {
229			config = &HybridSearchConfig{}
230		}
231		config.applyDefaults()
232	
233		var filterFileID string
234		if filter != nil {
235			if fid, ok := filter["file_id"].(string); ok {
236				filterFileID = fid
237			}
238		}
239	
240		// Build the set of candidate chunk IDs (respecting file_id filter).
241		candidates := make(map[string]EmbeddedChunk)
242		for id, chunk := range col.chunks {
243			if filterFileID != "" && chunk.FileID != filterFileID {
244				continue
245			}
246			candidates[id] = chunk
247		}
248	
249		// 1. Vector similarity scores.
250		vectorScores := make(map[string]float64, len(candidates))
251		for id, chunk := range candidates {
252			sim := cosineSimilarity(queryEmbedding, chunk.Embedding)
253			if sim > 0 {
254				vectorScores[id] = sim
255			}
256		}
257	
258		// 2. BM25 scores (use the pre-built index, score with request-time k1/b).
259		var bm25Scores map[string]float64
260		if col.bm25Index != nil {
261			allBM25 := col.bm25Index.Score(query, config.BM25K1, config.BM25B)
262			if filterFileID != "" {
263				bm25Scores = make(map[string]float64)
264				for id, s := range allBM25 {
265					if _, ok := candidates[id]; ok {
266						bm25Scores[id] = s
267					}
268				}
269			} else {
270				bm25Scores = allBM25
271			}
272		}
273	
274		// 3. N-gram scores. Rebuild if requested size differs from pre-built index.
275		var ngramScores map[string]float64
276		ngramIdx := col.ngramIndex
277		if ngramIdx != nil && ngramIdx.NgramN() != config.NgramSize {
278			ngramIdx = NewNgramIndex(col.chunks, config.NgramSize)
279		}
280		if ngramIdx != nil {
281			allNgram := ngramIdx.Score(query)
282			if filterFileID != "" {
283				ngramScores = make(map[string]float64)
284				for id, s := range allNgram {
285					if _, ok := candidates[id]; ok {
286						ngramScores[id] = s
287					}
288				}
289			} else {
290				ngramScores = allNgram
291			}
292		}
293	
294		// 4. Fuse scores.
295		fused := FuseScores(vectorScores, bm25Scores, ngramScores, config)
296	
297		// 5. Apply threshold and topK, build results.
298		results := make([]SearchResult, 0, topK)
299		for _, fc := range fused {
300			if fc.FinalScore < float64(threshold) {
301				continue
302			}
303			chunk, ok := col.chunks[fc.ChunkID]
304			if !ok {
305				continue
306			}
307			vs := fc.VectorScore
308			bs := fc.BM25Score
309			ns := fc.NgramScore
310			results = append(results, SearchResult{
311				FileID:      chunk.FileID,
312				Filename:    chunk.Filename,
313				Content:     chunk.Content,
314				Score:       fc.FinalScore,
315				ChunkIndex:  chunk.ChunkIndex,
316				VectorScore: &vs,
317				BM25Score:   &bs,
318				NgramScore:  &ns,
319			})
320			if topK > 0 && len(results) >= topK {
321				break
322			}
323		}
324	
325		return results, nil
326	}
327	
328	// Close is a no-op for the in-memory backend.
329	func (m *MemoryBackend) Close() error {
330		return nil
331	}
332	
333	// cosineSimilarity computes the cosine similarity between two vectors.
334	func cosineSimilarity(a, b []float32) float64 {
335		if len(a) != len(b) || len(a) == 0 {
336			return 0
337		}
338	
339		var dot, normA, normB float64
340		for i := range a {
341			dot += float64(a[i]) * float64(b[i])
342			normA += float64(a[i]) * float64(a[i])
343			normB += float64(b[i]) * float64(b[i])
344		}
345	
346		denom := math.Sqrt(normA) * math.Sqrt(normB)
347		if denom == 0 {
348			return 0
349		}
350		return dot / denom
351	}
