31	// safeIdentifierPattern matches UUIDs, prefixed IDs (file_xxx, vs_xxx), and simple alphanumeric strings.
32	// Used to prevent Milvus expression injection in filter values.
33	var safeIdentifierPattern = regexp.MustCompile(`^[a-zA-Z0-9_\-]+$`)
34	
35	// MilvusBackendConfig holds configuration for the Milvus backend.
36	type MilvusBackendConfig struct {
37		Address          string // host:port
38		CollectionPrefix string // prefix for collection names (default "vsr_vs_")
39		IndexM           int    // HNSW M parameter (default 16)
40		IndexEf          int    // HNSW efConstruction (default 200)
41		SearchEf         int    // search ef parameter (default 64)
42		ConnectTimeout   int    // connection timeout in seconds (default 10)
43	}
44	
45	// MilvusBackend implements VectorStoreBackend using Milvus.
46	type MilvusBackend struct {
47		client           client.Client
48		collectionPrefix string
49		indexM           int
50		indexEf          int
51		searchEf         int
52	}
53	
54	// NewMilvusBackend creates a new Milvus vector store backend.
55	func NewMilvusBackend(cfg MilvusBackendConfig) (*MilvusBackend, error) {
56		if cfg.Address == "" {
57			return nil, fmt.Errorf("milvus address is required")
58		}
59	
60		prefix := cfg.CollectionPrefix
61		if prefix == "" {
62			prefix = "vsr_vs_"
63		}
64		indexM := cfg.IndexM
65		if indexM <= 0 {
66			indexM = 16
67		}
68		indexEf := cfg.IndexEf
69		if indexEf <= 0 {
70			indexEf = 200
71		}
72		searchEf := cfg.SearchEf
73		if searchEf <= 0 {
74			searchEf = 64
75		}
76	
77		timeout := cfg.ConnectTimeout
78		if timeout <= 0 {
79			timeout = 10
80		}
81	
82		milvusClient, err := milvuslifecycle.ConnectGRPC(
83			context.Background(),
84			cfg.Address,
85			time.Duration(timeout)*time.Second,
86		)
87		if err != nil {
88			return nil, err
89		}
90	
91		return &MilvusBackend{
92			client:           milvusClient,
93			collectionPrefix: prefix,
94			indexM:           indexM,
95			indexEf:          indexEf,
96			searchEf:         searchEf,
97		}, nil
98	}
99	
100	func (m *MilvusBackend) collectionName(vectorStoreID string) string {
101		return m.collectionPrefix + vectorStoreID
102	}
103	
104	// CreateCollection creates a Milvus collection with the schema for document chunks.
105	func (m *MilvusBackend) CreateCollection(ctx context.Context, vectorStoreID string, dimension int) error {
106		colName := m.collectionName(vectorStoreID)
107	
108		// Keep CreateCollection semantics strict across backends.
109		exists, err := m.client.HasCollection(ctx, colName)
110		if err != nil {
111			return fmt.Errorf("failed to check existence of collection %q: %w", colName, err)
112		}
113		if exists {
114			return fmt.Errorf("collection %q already exists", colName)
115		}
116	
117		return milvuslifecycle.EnsureCollectionLoadedWithRetry(ctx, m.client, colName, func(innerCtx context.Context) error {
118			schema := &entity.Schema{
119				CollectionName: colName,
120				Description:    fmt.Sprintf("Vector store: %s", vectorStoreID),
121				Fields: []*entity.Field{
122					{
123						Name:       "id",
124						DataType:   entity.FieldTypeVarChar,
125						PrimaryKey: true,
126						TypeParams: map[string]string{"max_length": "128"},
127					},
128					{
129						Name:       "file_id",
130						DataType:   entity.FieldTypeVarChar,
131						TypeParams: map[string]string{"max_length": "128"},
132					},
133					{
134						Name:       "filename",
135						DataType:   entity.FieldTypeVarChar,
136						TypeParams: map[string]string{"max_length": "512"},
137					},
138					{
139						Name:       "content",
140						DataType:   entity.FieldTypeVarChar,
141						TypeParams: map[string]string{"max_length": "65535"},
142					},
143					{
144						Name:     "embedding",
145						DataType: entity.FieldTypeFloatVector,
146						TypeParams: map[string]string{
147							"dim": fmt.Sprintf("%d", dimension),
148						},
149					},
150					{
151						Name:     "chunk_index",
152						DataType: entity.FieldTypeInt64,
153					},
154					{
155						Name:     "created_at",
156						DataType: entity.FieldTypeInt64,
157					},
158				},
159			}
160	
161			if err := m.client.CreateCollection(innerCtx, schema, 1); err != nil {
162				return err
163			}
164	
165			// Create HNSW index on the embedding field.
166			index, err := entity.NewIndexHNSW(entity.IP, m.indexM, m.indexEf)
167			if err != nil {
168				return fmt.Errorf("failed to create HNSW index: %w", err)
169			}
170			if err := m.client.CreateIndex(innerCtx, colName, "embedding", index, false); err != nil {
171				return fmt.Errorf("failed to create index on %s: %w", colName, err)
172			}
173			return nil
174		}, milvuslifecycle.CollectionRetryOptions{})
175	}
176	
177	// DeleteCollection drops a Milvus collection.
178	func (m *MilvusBackend) DeleteCollection(ctx context.Context, vectorStoreID string) error {
179		colName := m.collectionName(vectorStoreID)
180		if err := m.client.DropCollection(ctx, colName); err != nil {
181			return fmt.Errorf("failed to drop collection %s: %w", colName, err)
182		}
183		return nil
184	}
185	
186	// CollectionExists checks if a Milvus collection exists.
187	func (m *MilvusBackend) CollectionExists(ctx context.Context, vectorStoreID string) (bool, error) {
188		colName := m.collectionName(vectorStoreID)
189		exists, err := m.client.HasCollection(ctx, colName)
190		if err != nil {
191			return false, fmt.Errorf("failed to check collection %s: %w", colName, err)
192		}
193		return exists, nil
194	}
195	
196	// InsertChunks inserts embedded chunks into the Milvus collection.
197	func (m *MilvusBackend) InsertChunks(ctx context.Context, vectorStoreID string, chunks []EmbeddedChunk) error {
198		if len(chunks) == 0 {
199			return nil
200		}
201	
202		colName := m.collectionName(vectorStoreID)
203		now := time.Now().Unix()
204	
205		ids := make([]string, len(chunks))
206		fileIDs := make([]string, len(chunks))
207		filenames := make([]string, len(chunks))
208		contents := make([]string, len(chunks))
209		embeddings := make([][]float32, len(chunks))
210		chunkIndices := make([]int64, len(chunks))
211		createdAts := make([]int64, len(chunks))
212	
213		for i, c := range chunks {
214			ids[i] = c.ID
215			fileIDs[i] = c.FileID
216			filenames[i] = c.Filename
217			contents[i] = c.Content
218			embeddings[i] = c.Embedding
219			chunkIndices[i] = int64(c.ChunkIndex)
220			createdAts[i] = now
221		}
222	
223		dim := len(chunks[0].Embedding)
224	
225		_, err := m.client.Upsert(ctx, colName, "",
226			entity.NewColumnVarChar("id", ids),
227			entity.NewColumnVarChar("file_id", fileIDs),
228			entity.NewColumnVarChar("filename", filenames),
229			entity.NewColumnVarChar("content", contents),
230			entity.NewColumnFloatVector("embedding", dim, embeddings),
231			entity.NewColumnInt64("chunk_index", chunkIndices),
232			entity.NewColumnInt64("created_at", createdAts),
233		)
234		if err != nil {
235			return fmt.Errorf("failed to insert chunks into %s: %w", colName, err)
236		}
237	
238		if err := m.client.Flush(ctx, colName, false); err != nil {
239			return fmt.Errorf("failed to flush %s: %w", colName, err)
240		}
241	
242		return nil
243	}
244	
245	// DeleteByFileID removes all chunks from a collection that belong to the given file.
246	func (m *MilvusBackend) DeleteByFileID(ctx context.Context, vectorStoreID string, fileID string) error {
247		if !safeIdentifierPattern.MatchString(fileID) {
248			return fmt.Errorf("invalid file ID: contains disallowed characters")
249		}
250		colName := m.collectionName(vectorStoreID)
251		expr := fmt.Sprintf("file_id == \"%s\"", fileID)
252	
253		if err := m.client.Delete(ctx, colName, "", expr); err != nil {
254			return fmt.Errorf("failed to delete chunks for file %s from %s: %w", fileID, colName, err)
255		}
256		return nil
257	}
258	
259	// Search performs vector similarity search in a Milvus collection.
260	//
261	//nolint:gocognit,cyclop,funlen
262	func (m *MilvusBackend) Search(
263		ctx context.Context, vectorStoreID string, queryEmbedding []float32,
264		topK int, threshold float32, filter map[string]interface{},
265	) ([]SearchResult, error) {
266		colName := m.collectionName(vectorStoreID)
267	
268		// Build filter expression with injection prevention.
269		expr := ""
270		if filter != nil {
271			if fid, ok := filter["file_id"].(string); ok && fid != "" {
272				if !safeIdentifierPattern.MatchString(fid) {
273					return nil, fmt.Errorf("invalid file_id filter: contains disallowed characters")
274				}
275				expr = fmt.Sprintf("file_id == \"%s\"", fid)
276			}
277		}
278	
279		sp, err := entity.NewIndexHNSWSearchParam(m.searchEf)
280		if err != nil {
281			return nil, fmt.Errorf("failed to create search params: %w", err)
282		}
283	
284		searchResults, err := m.client.Search(ctx, colName, []string{}, expr,
285			[]string{"file_id", "filename", "content", "chunk_index"},
286			[]entity.Vector{entity.FloatVector(queryEmbedding)},
287			"embedding", entity.IP, topK, sp)
288		if err != nil {
289			return nil, fmt.Errorf("failed to search in %s: %w", colName, err)
290		}
291	
292		var results []SearchResult
293		for _, sr := range searchResults {
294			for i := 0; i < sr.ResultCount; i++ {
295				score := float64(sr.Scores[i])
296				if score < float64(threshold) {
297					continue
298				}
299	
300				result := SearchResult{Score: score}
301	
302				// Extract field values by column name.
303				for _, field := range sr.Fields {
304					switch col := field.(type) {
305					case *entity.ColumnVarChar:
306						val, err := col.ValueByIdx(i)
307						if err != nil {
308							continue
309						}
310						switch col.Name() {
311						case "file_id":
312							result.FileID = val
313						case "filename":
314							result.Filename = val
315						case "content":
316							result.Content = val
317						}
318					case *entity.ColumnInt64:
319						val, err := col.ValueByIdx(i)
320						if err != nil {
321							continue
322						}
323						if col.Name() == "chunk_index" {
324							result.ChunkIndex = int(val)
325						}
326					}
327				}
328	
329				results = append(results, result)
330			}
331		}
332	
333		return results, nil
334	}
335	
336	// Close releases the Milvus client connection.
337	func (m *MilvusBackend) Close() error {
338		if m.client != nil {
339			return m.client.Close()
340		}
341		return nil
342	}
