15	*/
16	
17	package vectorstore
18	
19	import (
20		"context"
21		"fmt"
22		"math"
23		"sort"
24		"strings"
25		"unicode"
26	)
27	
28	// HybridSearcher is an optional interface that backends can implement
29	// to support hybrid search combining vector similarity with BM25 and
30	// n-gram text matching.
31	type HybridSearcher interface {
32		HybridSearch(ctx context.Context, vectorStoreID string,
33			query string, queryEmbedding []float32,
34			topK int, threshold float32,
35			filter map[string]interface{},
36			config *HybridSearchConfig,
37		) ([]SearchResult, error)
38	}
39	
40	// HybridSearchConfig configures hybrid search behavior.
41	type HybridSearchConfig struct {
42		// Mode selects the score fusion method: "weighted" (default) or "rrf".
43		Mode string `json:"mode,omitempty"`
44	
45		// Weights for weighted mode. Relative values; normalized to sum to 1.0.
46		VectorWeight float64 `json:"vector_weight,omitempty"` // default 0.7
47		BM25Weight   float64 `json:"bm25_weight,omitempty"`   // default 0.2
48		NgramWeight  float64 `json:"ngram_weight,omitempty"`  // default 0.1
49	
50		// RRFConstant for RRF mode (default 60).
51		RRFConstant int `json:"rrf_constant,omitempty"`
52	
53		// BM25K1 controls term frequency saturation (default 1.2).
54		BM25K1 float64 `json:"bm25_k1,omitempty"`
55		// BM25B controls document length normalization (default 0.75).
56		BM25B float64 `json:"bm25_b,omitempty"`
57	
58		// NgramSize is the character n-gram size for Jaccard similarity (default 3).
59		NgramSize int `json:"ngram_size,omitempty"`
60	}
61	
62	func (c *HybridSearchConfig) applyDefaults() {
63		if c.Mode == "" {
64			c.Mode = "weighted"
65		}
66		if c.VectorWeight == 0 && c.BM25Weight == 0 && c.NgramWeight == 0 {
67			c.VectorWeight = 0.7
68			c.BM25Weight = 0.2
69			c.NgramWeight = 0.1
70		}
71		if c.RRFConstant <= 0 {
72			c.RRFConstant = 60
73		}
74		if c.BM25K1 == 0 {
75			c.BM25K1 = 1.2
76		}
77		if c.BM25B == 0 {
78			c.BM25B = 0.75
79		}
80		if c.NgramSize <= 0 {
81			c.NgramSize = 3
82		}
83	}
84	
85	// normalizedWeights returns vector, bm25, ngram weights that sum to 1.
86	func (c *HybridSearchConfig) normalizedWeights() (float64, float64, float64) {
87		total := c.VectorWeight + c.BM25Weight + c.NgramWeight
88		if total == 0 {
89			return 1.0 / 3, 1.0 / 3, 1.0 / 3
90		}
91		return c.VectorWeight / total, c.BM25Weight / total, c.NgramWeight / total
92	}
93	
94	// ---------------------------------------------------------------------------
95	// BM25 Index
96	// ---------------------------------------------------------------------------
97	
98	type bm25Doc struct {
99		chunkID string
100		terms   map[string]int // term -> frequency
101		length  int
102	}
103	
104	// BM25Index is a pre-built inverted index that supports BM25 scoring
105	// with configurable k1/b parameters at query time.
106	type BM25Index struct {
107		docs  []bm25Doc
108		df    map[string]int // term -> document frequency
109		avgDL float64
110		n     int // total number of documents
111	}
112	
113	// NewBM25Index builds a BM25 inverted index over the given chunks.
114	func NewBM25Index(chunks map[string]EmbeddedChunk) *BM25Index {
115		idx := &BM25Index{
116			docs: make([]bm25Doc, 0, len(chunks)),
117			df:   make(map[string]int),
118		}
119	
120		totalLen := 0
121		for id, chunk := range chunks {
122			tokens := tokenize(chunk.Content)
123			tf := make(map[string]int, len(tokens))
124			for _, t := range tokens {
125				tf[t]++
126			}
127			idx.docs = append(idx.docs, bm25Doc{
128				chunkID: id,
129				terms:   tf,
130				length:  len(tokens),
131			})
132			// Count each term once for this document; tf keys are already unique.
133			for term := range tf {
134				idx.df[term]++
135			}
136			totalLen += len(tokens)
137		}
138	
139		idx.n = len(idx.docs)
140		if idx.n > 0 {
141			idx.avgDL = float64(totalLen) / float64(idx.n)
142		}
143	
144		return idx
145	}
146	
147	// Score returns BM25 scores for all documents against the query.
148	func (idx *BM25Index) Score(query string, k1, b float64) map[string]float64 {
149		if idx.n == 0 {
150			return nil
151		}
152	
153		queryTerms := tokenize(query)
154		if len(queryTerms) == 0 {
155			return nil
156		}
157	
158		// Pre-compute IDF for query terms only.
159		idfCache := make(map[string]float64, len(queryTerms))
160		for _, qt := range queryTerms {
161			if _, ok := idfCache[qt]; ok {
162				continue
163			}
164			n := float64(idx.df[qt])
165			if n == 0 {
166				idfCache[qt] = 0
167				continue
168			}
169			idfCache[qt] = math.Log((float64(idx.n)-n+0.5)/(n+0.5) + 1)
170		}
171	
172		scores := make(map[string]float64)
173		for _, doc := range idx.docs {
174			var score float64
175			for _, qt := range queryTerms {
176				idf := idfCache[qt]
177				if idf == 0 {
178					continue
179				}
180				tf := float64(doc.terms[qt])
181				if tf == 0 {
182					continue
183				}
184				num := tf * (k1 + 1)
185				denom := tf + k1*(1-b+b*float64(doc.length)/idx.avgDL)
186				score += idf * num / denom
187			}
188			if score > 0 {
189				scores[doc.chunkID] = score
190			}
191		}
192	
193		return scores
194	}
195	
196	// ---------------------------------------------------------------------------
197	// N-gram Index
198	// ---------------------------------------------------------------------------
199	
200	// NgramIndex stores pre-computed character n-gram sets for Jaccard similarity.
201	type NgramIndex struct {
202		chunkNgrams map[string]map[string]struct{}
203		n           int
204	}
205	
206	// NewNgramIndex builds an n-gram index over the given chunks.
207	func NewNgramIndex(chunks map[string]EmbeddedChunk, n int) *NgramIndex {
208		idx := &NgramIndex{
209			chunkNgrams: make(map[string]map[string]struct{}, len(chunks)),
210			n:           n,
211		}
212		for id, chunk := range chunks {
213			idx.chunkNgrams[id] = charNgrams(strings.ToLower(chunk.Content), n)
214		}
215		return idx
216	}
217	
218	// Score returns Jaccard similarity in [0,1] for all chunks against the query.
219	func (idx *NgramIndex) Score(query string) map[string]float64 {
220		if len(idx.chunkNgrams) == 0 {
221			return nil
222		}
223	
224		queryGrams := charNgrams(strings.ToLower(query), idx.n)
225		if len(queryGrams) == 0 {
226			return nil
227		}
228	
229		scores := make(map[string]float64)
230		for chunkID, docGrams := range idx.chunkNgrams {
231			sim := jaccardSimilarity(queryGrams, docGrams)
232			if sim > 0 {
233				scores[chunkID] = sim
234			}
235		}
236		return scores
237	}
238	
239	// NgramN returns the n-gram size this index was built with.
240	func (idx *NgramIndex) NgramN() int {
241		return idx.n
242	}
243	
244	// ---------------------------------------------------------------------------
245	// Tokenizer
246	// ---------------------------------------------------------------------------
247	
248	// tokenize splits text into lowercase tokens on non-alphanumeric boundaries.
249	func tokenize(text string) []string {
250		var tokens []string
251		lower := strings.ToLower(text)
252		start := -1
253		for i, r := range lower {
254			if unicode.IsLetter(r) || unicode.IsDigit(r) {
255				if start < 0 {
256					start = i
257				}
258				continue
259			}
260			if start >= 0 {
261				// Clone token slices so retained index terms do not pin the full lowercased chunk in memory.
262				tokens = append(tokens, strings.Clone(lower[start:i]))
263				start = -1
264			}
265		}
266		if start >= 0 {
267			tokens = append(tokens, strings.Clone(lower[start:]))
268		}
269		return tokens
270	}
271	
272	// ---------------------------------------------------------------------------
273	// N-gram helpers
274	// ---------------------------------------------------------------------------
275	
276	// charNgrams generates the set of character n-grams from text.
277	func charNgrams(text string, n int) map[string]struct{} {
278		runes := []rune(text)
279		if len(runes) < n {
280			result := make(map[string]struct{})
281			if len(runes) > 0 {
282				result[string(runes)] = struct{}{}
283			}
284			return result
285		}
286		result := make(map[string]struct{}, len(runes)-n+1)
287		for i := 0; i <= len(runes)-n; i++ {
288			result[string(runes[i:i+n])] = struct{}{}
289		}
290		return result
291	}
292	
293	// jaccardSimilarity computes |A ∩ B| / |A ∪ B|.
294	func jaccardSimilarity(a, b map[string]struct{}) float64 {
295		if len(a) == 0 && len(b) == 0 {
296			return 0
297		}
298		intersection := 0
299		for k := range a {
300			if _, ok := b[k]; ok {
301				intersection++
302			}
303		}
304		union := len(a) + len(b) - intersection
305		if union == 0 {
306			return 0
307		}
308		return float64(intersection) / float64(union)
309	}
310	
311	// ---------------------------------------------------------------------------
312	// Score Fusion
313	// ---------------------------------------------------------------------------
314	
315	// FusedChunk holds per-retriever scores for a single chunk.
316	type FusedChunk struct {
317		ChunkID     string
318		VectorScore float64
319		BM25Score   float64
320		NgramScore  float64
321		FinalScore  float64
322	}
323	
324	// FuseScores combines scores from vector, BM25, and n-gram retrievers
325	// using either weighted combination or Reciprocal Rank Fusion (RRF).
326	// Returns fused results sorted by finalScore descending.
327	func FuseScores(
328		vectorScores, bm25Scores, ngramScores map[string]float64,
329		config *HybridSearchConfig,
330	) []FusedChunk {
331		config.applyDefaults()
332	
333		all := make(map[string]*FusedChunk)
334		for id, s := range vectorScores {
335			all[id] = &FusedChunk{ChunkID: id, VectorScore: s}
336		}
337		for id, s := range bm25Scores {
338			if fc, ok := all[id]; ok {
339				fc.BM25Score = s
340			} else {
341				all[id] = &FusedChunk{ChunkID: id, BM25Score: s}
342			}
343		}
344		for id, s := range ngramScores {
345			if fc, ok := all[id]; ok {
346				fc.NgramScore = s
347			} else {
348				all[id] = &FusedChunk{ChunkID: id, NgramScore: s}
349			}
350		}
351	
352		if config.Mode == "rrf" {
353			fuseRRF(all, vectorScores, bm25Scores, ngramScores, config.RRFConstant)
354		} else {
355			fuseWeighted(all, config)
356		}
357	
358		results := make([]FusedChunk, 0, len(all))
359		for _, fc := range all {
360			results = append(results, *fc)
361		}
362		sort.Slice(results, func(i, j int) bool {
363			return results[i].FinalScore > results[j].FinalScore
364		})
365		return results
366	}
367	
368	// fuseWeighted computes weighted sum with min-max normalization for BM25.
369	// Vector scores (cosine) and n-gram scores (Jaccard) are already in [0,1].
370	func fuseWeighted(all map[string]*FusedChunk, config *HybridSearchConfig) {
371		wV, wB, wN := config.normalizedWeights()
372	
373		// Min-max normalize BM25 scores (they are unbounded).
374		var bm25Min, bm25Max float64
375		first := true
376		for _, fc := range all {
377			if fc.BM25Score == 0 {
378				continue
379			}
380			if first {
381				bm25Min, bm25Max = fc.BM25Score, fc.BM25Score
382				first = false
383			} else {
384				if fc.BM25Score < bm25Min {
385					bm25Min = fc.BM25Score
386				}
387				if fc.BM25Score > bm25Max {
388					bm25Max = fc.BM25Score
389				}
390			}
391		}
392		bm25Range := bm25Max - bm25Min
393	
394		for _, fc := range all {
395			normBM25 := 0.0
396			if bm25Range > 0 {
397				normBM25 = (fc.BM25Score - bm25Min) / bm25Range
398			} else if fc.BM25Score > 0 {
399				normBM25 = 1.0
400			}
401			fc.FinalScore = wV*fc.VectorScore + wB*normBM25 + wN*fc.NgramScore
402		}
403	}
404	
405	// fuseRRF applies Reciprocal Rank Fusion: score(d) = Σ_r 1/(k + rank_r(d)).
406	func fuseRRF(
407		all map[string]*FusedChunk,
408		vectorScores, bm25Scores, ngramScores map[string]float64,
409		k int,
410	) {
411		kf := float64(k)
412	
413		addRanks := func(scores map[string]float64) {
414			if len(scores) == 0 {
415				return
416			}
417			type entry struct {
418				id    string
419				score float64
420			}
421			sorted := make([]entry, 0, len(scores))
422			for id, s := range scores {
423				sorted = append(sorted, entry{id, s})
424			}
425			sort.Slice(sorted, func(i, j int) bool {
426				return sorted[i].score > sorted[j].score
427			})
428			for rank, e := range sorted {
429				if fc, ok := all[e.id]; ok {
430					fc.FinalScore += 1.0 / (kf + float64(rank+1))
431				}
432			}
433		}
434	
435		addRanks(vectorScores)
436		addRanks(bm25Scores)
437		addRanks(ngramScores)
438	}
439	
440	// ---------------------------------------------------------------------------
441	// Generic Hybrid Rerank (works with any VectorStoreBackend)
442	// ---------------------------------------------------------------------------
443	
444	// rerankCandidateMultiplier controls how many extra candidates to fetch from
445	// the base vector search so that text-based re-ranking has a richer pool.
446	const rerankCandidateMultiplier = 4
447	
448	// GenericHybridRerank performs hybrid search on any backend by re-ranking
449	// the results of the backend's existing vector Search method with BM25 and
450	// n-gram text scores. This is the fallback path for backends that do not
451	// implement HybridSearcher natively (e.g. Milvus, Llama Stack).
452	//
453	// Flow:
454	//  1. Call backend.Search with an expanded topK (4x) and threshold=0 to get
455	//     a broad candidate set from vector similarity.
456	//  2. Build ephemeral BM25 and n-gram indexes over the candidate contents.
457	//  3. Fuse the three score signals using the configured mode (weighted / RRF).
458	//  4. Apply the caller's threshold and topK to the fused results.
459	func GenericHybridRerank(
460		ctx context.Context,
461		backend VectorStoreBackend,
462		vectorStoreID string,
463		query string,
464		queryEmbedding []float32,
465		topK int,
466		threshold float32,
467		filter map[string]interface{},
468		config *HybridSearchConfig,
469	) ([]SearchResult, error) {
470		if config == nil {
471			config = &HybridSearchConfig{}
472		}
473		config.applyDefaults()
474	
475		// Fetch an expanded candidate set from the base vector search.
476		expandedTopK := topK * rerankCandidateMultiplier
477		if expandedTopK < 50 {
478			expandedTopK = 50
479		}
480	
481		vectorResults, err := backend.Search(ctx, vectorStoreID, queryEmbedding,
482			expandedTopK, 0, filter)
483		if err != nil {
484			return nil, fmt.Errorf("hybrid rerank: vector search failed: %w", err)
485		}
486	
487		if len(vectorResults) == 0 {
488			return vectorResults, nil
489		}
490	
491		// Build pseudo-chunks keyed by a stable index ID so the BM25 / n-gram
492		// indexes can reference the same candidates as the vector results.
493		pseudoChunks := make(map[string]EmbeddedChunk, len(vectorResults))
494		vectorScores := make(map[string]float64, len(vectorResults))
495		idxToKey := make([]string, len(vectorResults))
496	
497		for i, r := range vectorResults {
498			key := fmt.Sprintf("_rr_%d", i)
499			idxToKey[i] = key
500			pseudoChunks[key] = EmbeddedChunk{ID: key, Content: r.Content}
501			vectorScores[key] = r.Score
502		}
503	
504		// Score with BM25.
505		bm25Idx := NewBM25Index(pseudoChunks)
506		bm25Scores := bm25Idx.Score(query, config.BM25K1, config.BM25B)
507	
508		// Score with n-gram.
509		ngramIdx := NewNgramIndex(pseudoChunks, config.NgramSize)
510		ngramScores := ngramIdx.Score(query)
511	
512		// Fuse.
513		fused := FuseScores(vectorScores, bm25Scores, ngramScores, config)
514	
515		// Map fused chunk keys back to original results.
516		keyToIdx := make(map[string]int, len(idxToKey))
517		for i, k := range idxToKey {
518			keyToIdx[k] = i
519		}
520	
521		results := make([]SearchResult, 0, topK)
522		for _, fc := range fused {
523			if fc.FinalScore < float64(threshold) {
524				continue
525			}
526			origIdx, ok := keyToIdx[fc.ChunkID]
527			if !ok {
528				continue
529			}
530			orig := vectorResults[origIdx]
531			vs := fc.VectorScore
532			bs := fc.BM25Score
533			ns := fc.NgramScore
534			results = append(results, SearchResult{
535				FileID:      orig.FileID,
536				Filename:    orig.Filename,
537				Content:     orig.Content,
538				Score:       fc.FinalScore,
539				ChunkIndex:  orig.ChunkIndex,
540				VectorScore: &vs,
541				BM25Score:   &bs,
542				NgramScore:  &ns,
543			})
544			if topK > 0 && len(results) >= topK {
545				break
546			}
547		}
548	
549		return results, nil
550	}
551

